import json, statistics, re, collections
from pathlib import Path
from tokenizers import Tokenizer
tok=Tokenizer.from_file('models/Qwen2.5-0.5B-Instruct/tokenizer.json')
for folder in ['val_generations','rollouts']:
 for f in sorted(Path('results/run100',folder).glob('*.jsonl'),key=lambda p:int(p.stem)):
  rows=[json.loads(l) for l in f.open()]
  enc=tok.encode_batch([r['output'] for r in rows],add_special_tokens=False)
  lens=[len(e.ids) for e in enc]
  groups=collections.defaultdict(list)
  for i,r in enumerate(rows): groups[r['input']].append(i)
  long=[i for i,l in enumerate(lens) if l>=511]
  nonascii=[i for i,r in enumerate(rows) if sum(ord(c)>127 for c in r['output'])>20]
  repeats=[i for i,r in enumerate(rows) if re.search(r'(.{1,30}?)\1{14,}',r['output'])]
  print('\n',f,'long',len(long),'nonascii>20',len(nonascii),'repeat15',len(repeats),'degenerate union',len(set(nonascii+repeats)), 'long overlap degenerate',len(set(long)&set(nonascii+repeats)))
  print('degenerate with reward',[(i,rows[i]['score']) for i in sorted(set(nonascii+repeats)) if rows[i]['score']][:10])
  if folder=='rollouts':
   hs=collections.Counter(sum(rows[i]['score'] for i in idx) for idx in groups.values())
   print('successes per group',dict(sorted(hs.items())))
   adv=[]
   for idx in groups.values():
    scores=[rows[i]['score'] for i in idx]; mu=statistics.mean(scores); sd=statistics.stdev(scores)
    for i in idx: adv.append((i,(rows[i]['score']-mu)/(sd+1e-6)))
   print('approx token-weighted mean advantage',sum(lens[i]*a for i,a in adv)/sum(lens),'long negative',sum(a<0 for i,a in adv if i in long),'long zero',sum(a==0 for i,a in adv if i in long))
  if folder=='val_generations':
