import json,collections,re,statistics
rs={s:[json.loads(l) for l in open(f'results/run100/val_generations/{s}.jsonl')] for s in [0,50,100]}
def numeric(r):
 nums=re.findall(r'\-?[0-9]+(?:,[0-9]{3})*(?:\.[0-9]+)?',r['output'][-300:])
 return bool(nums) and nums[-1].replace(',','').rstrip('.')==r['gts']
def loop(r):
 return any(any(c.isalnum() for c in m.group(1)) for m in re.finditer(r'([^\n]{1,24}?)\1{14,}',r['output']))
for s in [50,100]:
 print('step',s,'last numeric heuristic paired',collections.Counter((numeric(a),numeric(b)) for a,b in zip(rs[0],rs[s])))
 print('step',s,'baseline numeric correct -> loop',sum(numeric(a) and loop(b) for a,b in zip(rs[0],rs[s])))
 print('step',s,'loop ids', [i+1 for i,r in enumerate(rs[s]) if loop(r)][:15])
for k in ['critic/advantages/mean','actor/pg_loss','actor/kl_loss','actor/loss']:
 print(k,[(s,next(json.loads(l)['data'][k] for l in open('results/run100/metrics.jsonl') if json.loads(l)['step']==s)) for s in [1,50,100]])
